(async()=>{
const c=await import("node:crypto"),p=await import("pg");
const k=JSON.parse(process.env.INTERNAL_EVENT_API_PROJECT_KEYS_JSON)["server-core"];
const rid="req_"+c.randomBytes(12).toString("hex");
const b={eventId:rid,eventType:"gace.servercore-bounded-host.requested",sourceId:"server-core-github",destinationId:"server-core-bounded-host",data:{schema:"gace.servercore-bounded-host.request/v1",id:rid,command_id:"project.git_head",expected_sha:"7a9ea997f62167946991ecb7734c0859e2d9d57d"}};
const a=await fetch("http://127.0.0.1:7373/internal/events",{method:"POST",headers:{"content-type":"application/json","x-internal-api-token":k},body:JSON.stringify(b)});
console.log("INGRESS",rid,a.status);
if(a.status!==202)throw Error("INGRESS_REJECTED");
const d=new p.Client({connectionString:process.env.DATABASE_URL});await d.connect();
let state="NONE";
for(let i=0;i<15;i++){
const q=await d.query("SELECT d.status,d.last_status_code FROM events e JOIN deliveries d ON e.id=d.event_id WHERE e.source_id=$1 AND e.provider_event_id=$2",["server-core-github",rid]);
state=q.rows[0]?.status||"NONE";
if(["delivered","dead"].includes(state)){console.log("DELIVERY",rid,JSON.stringify(q.rows[0]));break}
await new Promise(r=>setTimeout(r,2000));
}
await d.end();
if(state!=="delivered")throw Error("NOT_DELIVERED_"+state);
})().catch(e=>{console.log("ERROR",e.message);process.exit(2)});
